import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { Users, MapPin, Calendar, ArrowLeft, UserPlus, UserMinus, Clock, Trophy, User } from 'lucide-react';
import { io } from 'socket.io-client';
import { getApiBaseUrl } from '../utils/api';

interface Participant {
  id: string;
  username: string;
  joined_at: string;
  team?: 'A' | 'B';
}

interface Game {
  id: string;
  title: string;
  sport: string;
  location: string;
  max_players: number;
  creator_name: string;
  created_at: string;
  game_time?: string;
}

interface PlayerProfile {
  id: string;
  username: string;
  email: string;
  games_played: number;
  games_won: number;
  favorite_sport: string;
  created_at: string;
}

const GameLobby: React.FC = () => {
  const { gameId } = useParams<{ gameId: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();

  const [game, setGame] = useState<Game | null>(null);
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showPlayerProfile, setShowPlayerProfile] = useState<string | null>(null);
  const [playerProfile, setPlayerProfile] = useState<PlayerProfile | null>(null);
  const [autoAssignTeams, setAutoAssignTeams] = useState(true);

  useEffect(() => {
    const apiBaseUrl = getApiBaseUrl();
    const newSocket = io(apiBaseUrl);

    const setupSocket = () => {
      newSocket.emit('join-game', gameId);

      newSocket.on('user-joined', (data) => {
        setParticipants(prev => [...prev, data.user]);
      });

      newSocket.on('user-left', (data) => {
        setParticipants(prev => prev.filter(p => p.id !== data.user.id));
      });

      newSocket.on('teams-updated', (data) => {
        setParticipants(data.participants);
      });
    };

    const fetchGameDetails = async () => {
      try {
        const response = await fetch(`${apiBaseUrl}/api/games`);
        if (response.ok) {
          const games = await response.json();
          const game = games.find((g: any) => g.id === gameId);
          if (game) {
            setGame(game);
          } else {
            setError('Game not found');
          }
        }
      } catch (error) {
        setError('Failed to load game details');
      }
    };

    const fetchParticipants = async () => {
      try {
        const response = await fetch(`${apiBaseUrl}/api/games/${gameId}/participants`);
        if (response.ok) {
          const data = await response.json();
          setParticipants(data);
        }
      } catch (error) {
        console.error('Error fetching participants:', error);
      } finally {
        setLoading(false);
      }
    };

    setupSocket();
    fetchGameDetails();
    fetchParticipants();

    return () => {
      newSocket.disconnect();
    };
  }, [gameId]);

  const leaveGame = async () => {
    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/games/${gameId}/leave`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        navigate('/');
      }
    } catch (error) {
      console.error('Error leaving game:', error);
    }
  };

  const assignTeams = async () => {
    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/games/${gameId}/assign-teams`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        const data = await response.json();
        setParticipants(data.participants);
      }
    } catch (error) {
      console.error('Error assigning teams:', error);
    }
  };

  const fetchPlayerProfile = async (userId: string) => {
    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/users/${userId}/profile`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        const profile = await response.json();
        setPlayerProfile(profile);
        setShowPlayerProfile(userId);
      }
    } catch (error) {
      console.error('Error fetching player profile:', error);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const formatTime = (timeString: string) => {
    return new Date(timeString).toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const teamAPlayers = participants.filter(p => p.team === 'A');
  const teamBPlayers = participants.filter(p => p.team === 'B');
  const unassignedPlayers = participants.filter(p => !p.team);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (error || !game) {
    return (
      <div className="max-w-4xl mx-auto">
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md">
          {error || 'Game not found'}
        </div>
        <button
          onClick={() => navigate('/')}
          className="mt-4 inline-flex items-center px-4 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 bg-white hover:bg-gray-50"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Dashboard
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto">
      {/* Player Profile Modal */}
      {showPlayerProfile && playerProfile && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold">Player Profile</h3>
              <button
                onClick={() => setShowPlayerProfile(null)}
                className="text-gray-400 hover:text-gray-600"
              >
                ✕
              </button>
            </div>
            <div className="space-y-4">
              <div className="flex items-center">
                <div className="w-12 h-12 bg-blue-500 rounded-full flex items-center justify-center text-white font-bold">
                  {playerProfile.username.charAt(0).toUpperCase()}
                </div>
                <div className="ml-4">
                  <h4 className="font-semibold">{playerProfile.username}</h4>
                  <p className="text-sm text-gray-600">{playerProfile.email}</p>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <p className="text-gray-600">Games Played</p>
                  <p className="font-semibold">{playerProfile.games_played}</p>
                </div>
                <div>
                  <p className="text-gray-600">Games Won</p>
                  <p className="font-semibold">{playerProfile.games_won}</p>
                </div>
                <div>
                  <p className="text-gray-600">Win Rate</p>
                  <p className="font-semibold">
                    {playerProfile.games_played > 0 
                      ? Math.round((playerProfile.games_won / playerProfile.games_played) * 100)
                      : 0}%
                  </p>
                </div>
                <div>
                  <p className="text-gray-600">Favorite Sport</p>
                  <p className="font-semibold capitalize">{playerProfile.favorite_sport}</p>
                </div>
              </div>
              <div className="text-xs text-gray-500">
                Member since {formatDate(playerProfile.created_at)}
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="mb-6">
        <button
          onClick={() => navigate('/')}
          className="inline-flex items-center text-sm text-gray-600 hover:text-gray-900 mb-4"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Dashboard
        </button>

        {/* Game Header */}
        <div className="bg-white bg-opacity-90 backdrop-blur-md rounded-lg shadow-xl p-6 border border-white border-opacity-20 mb-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-3xl font-bold text-gray-900">{game.title}</h1>
              <p className="text-xl text-gray-600 capitalize">{game.sport}</p>
            </div>
            <button
              onClick={leaveGame}
              className="inline-flex items-center px-4 py-2 border border-red-300 text-sm font-medium rounded-md text-red-700 bg-white hover:bg-red-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500"
            >
              <UserMinus className="w-4 h-4 mr-2" />
              Leave Game
            </button>
          </div>

          {/* Game Info Grid */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
            <div className="flex items-center text-sm text-gray-600 bg-gray-50 p-3 rounded-lg">
              <MapPin className="w-5 h-5 mr-2 text-blue-500" />
              <div>
                <p className="font-medium">Location</p>
                <p>{game.location}</p>
              </div>
            </div>
            <div className="flex items-center text-sm text-gray-600 bg-gray-50 p-3 rounded-lg">
              <Users className="w-5 h-5 mr-2 text-green-500" />
              <div>
                <p className="font-medium">Players</p>
                <p>{participants.length}/{game.max_players}</p>
              </div>
            </div>
            <div className="flex items-center text-sm text-gray-600 bg-gray-50 p-3 rounded-lg">
              <Calendar className="w-5 h-5 mr-2 text-purple-500" />
              <div>
                <p className="font-medium">Created</p>
                <p>{formatDate(game.created_at)}</p>
              </div>
            </div>
            {game.game_time && (
              <div className="flex items-center text-sm text-gray-600 bg-gray-50 p-3 rounded-lg">
                <Clock className="w-5 h-5 mr-2 text-orange-500" />
                <div>
                  <p className="font-medium">Game Time</p>
                  <p>{formatTime(game.game_time)}</p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Teams Section */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Team A */}
          <div className="bg-white bg-opacity-90 backdrop-blur-md rounded-lg shadow-xl p-6 border border-white border-opacity-20">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-red-600 flex items-center">
                <Trophy className="w-5 h-5 mr-2" />
                Team A
              </h2>
              <span className="bg-red-100 text-red-800 text-xs font-medium px-2.5 py-0.5 rounded-full">
                {teamAPlayers.length} players
              </span>
            </div>
            <div className="space-y-3">
              {teamAPlayers.map((participant) => (
                <div
                  key={participant.id}
                  className="flex items-center justify-between p-3 bg-red-50 rounded-lg cursor-pointer hover:bg-red-100 transition-colors"
                  onClick={() => fetchPlayerProfile(participant.id)}
                >
                  <div className="flex items-center">
                    <div className="w-8 h-8 bg-red-500 rounded-full flex items-center justify-center text-white text-sm font-medium">
                      {participant.username.charAt(0).toUpperCase()}
                    </div>
                    <div className="ml-3">
                      <p className="text-sm font-medium text-gray-900">{participant.username}</p>
                      <p className="text-xs text-gray-500">Joined {formatDate(participant.joined_at)}</p>
                    </div>
                  </div>
                  <User className="w-4 h-4 text-red-400" />
                </div>
              ))}
              {teamAPlayers.length === 0 && (
                <p className="text-gray-500 text-center py-4">No players assigned</p>
              )}
            </div>
          </div>

          {/* Team B */}
          <div className="bg-white bg-opacity-90 backdrop-blur-md rounded-lg shadow-xl p-6 border border-white border-opacity-20">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-blue-600 flex items-center">
                <Trophy className="w-5 h-5 mr-2" />
                Team B
              </h2>
              <span className="bg-blue-100 text-blue-800 text-xs font-medium px-2.5 py-0.5 rounded-full">
                {teamBPlayers.length} players
              </span>
            </div>
            <div className="space-y-3">
              {teamBPlayers.map((participant) => (
                <div
                  key={participant.id}
                  className="flex items-center justify-between p-3 bg-blue-50 rounded-lg cursor-pointer hover:bg-blue-100 transition-colors"
                  onClick={() => fetchPlayerProfile(participant.id)}
                >
                  <div className="flex items-center">
                    <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center text-white text-sm font-medium">
                      {participant.username.charAt(0).toUpperCase()}
                    </div>
                    <div className="ml-3">
                      <p className="text-sm font-medium text-gray-900">{participant.username}</p>
                      <p className="text-xs text-gray-500">Joined {formatDate(participant.joined_at)}</p>
                    </div>
                  </div>
                  <User className="w-4 h-4 text-blue-400" />
                </div>
              ))}
              {teamBPlayers.length === 0 && (
                <p className="text-gray-500 text-center py-4">No players assigned</p>
              )}
            </div>
          </div>

          {/* Unassigned Players & Controls */}
          <div className="bg-white bg-opacity-90 backdrop-blur-md rounded-lg shadow-xl p-6 border border-white border-opacity-20">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-gray-600 flex items-center">
                <Users className="w-5 h-5 mr-2" />
                Unassigned
              </h2>
              <span className="bg-gray-100 text-gray-800 text-xs font-medium px-2.5 py-0.5 rounded-full">
                {unassignedPlayers.length} players
              </span>
            </div>

            <div className="space-y-3 mb-4">
              {unassignedPlayers.map((participant) => (
                <div
                  key={participant.id}
                  className="flex items-center justify-between p-3 bg-gray-50 rounded-lg cursor-pointer hover:bg-gray-100 transition-colors"
                  onClick={() => fetchPlayerProfile(participant.id)}
                >
                  <div className="flex items-center">
                    <div className="w-8 h-8 bg-gray-500 rounded-full flex items-center justify-center text-white text-sm font-medium">
                      {participant.username.charAt(0).toUpperCase()}
                    </div>
                    <div className="ml-3">
                      <p className="text-sm font-medium text-gray-900">{participant.username}</p>
                      <p className="text-xs text-gray-500">Joined {formatDate(participant.joined_at)}</p>
                    </div>
                  </div>
                  <User className="w-4 h-4 text-gray-400" />
                </div>
              ))}
              {unassignedPlayers.length === 0 && (
                <p className="text-gray-500 text-center py-4">All players assigned</p>
              )}
            </div>

            {/* Team Controls */}
            <div className="border-t border-gray-200 pt-4">
              <div className="flex items-center justify-between mb-3">
                <label className="flex items-center">
                  <input
                    type="checkbox"
                    checked={autoAssignTeams}
                    onChange={(e) => setAutoAssignTeams(e.target.checked)}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                  />
                  <span className="ml-2 text-sm text-gray-700">Auto-assign teams</span>
                </label>
              </div>

              <button
                onClick={assignTeams}
                disabled={participants.length < 2}
                className="w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed transition-colors"
              >
                Assign Teams
              </button>
            </div>
          </div>
        </div>

        {/* Game Status */}
        {participants.length >= game.max_players && (
          <div className="mt-6 bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-md">
            🎉 Game is full! Ready to start playing!
          </div>
        )}
      </div>
    </div>
  );
};

export default GameLobby;
